css:
:root {
  /* Tipografía */
  --sdf-font-family: Arial, "Segoe UI", sans-serif;

  /* Colores del logotipo */
  --sdf-dark-color: #6D7170;
  --sdf-light-color: #A0A3A2;

  /* Texto */
  --sdf-company-font-size: 56px;
}

/* ==========================================================
   ENTORNO TRANSPARENTE
   ========================================================== */

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.sdf-widget {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  font-family: var(--sdf-font-family);
  pointer-events: none;
}

.sdf-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  shape-rendering: geometricPrecision;
}

/* Representación completamente estática */

.sdf-widget,
.sdf-widget * {
  animation: none !important;
  transition: none !important;
}

/* ==========================================================
   SÍMBOLO SDF
   ========================================================== */

.sdf-dark {
  fill: var(--sdf-dark-color);
  stroke: none;
}

.sdf-light {
  fill: var(--sdf-light-color);
  stroke: none;
}

/* ==========================================================
   NOMBRE DE LA EMPRESA
   ========================================================== */

.sdf-company-name {
  fill: var(--sdf-dark-color);
  stroke: none;
  font-family: var(--sdf-font-family);
  font-size: var(--sdf-company-font-size);
  font-weight: 700;
  text-anchor: start;
}
